import krlLinesJson from './krl-lines.json';
import { KRL_LINES, type KrlLineGeometry, type KrlLineMeta } from './krlLines';
import type { LatLngTuple } from './polyline';

export interface KrlLineLayer extends KrlLineMeta {
  paths: LatLngTuple[][];
}

// Generated by scripts/fetch-krl-lines.ts (OpenStreetMap data); see that script to refresh it.
const GEOMETRY = krlLinesJson as KrlLineGeometry[];

/**
 * KRL lines with their track geometry, in drawing order: the first line in KRL_LINES is
 * drawn last so it ends up on top where tracks are shared (e.g. Cikarang over Airport).
 */
export function getKrlLineLayers(geometry: KrlLineGeometry[] = GEOMETRY): KrlLineLayer[] {
  const pathsById = new Map(geometry.map((line) => [line.id, line.paths]));
  return KRL_LINES.flatMap((meta) => {
    const paths = pathsById.get(meta.id);
    return paths && paths.length > 0 ? [{ ...meta, paths }] : [];
  }).reverse();
}
